-- =============================================================================
-- Karthika - seed data
--
-- GENERATED FILE. Do not edit by hand: run `npm run db:seed` instead, which
-- regenerates it from src/lib/data/catalog.ts.
--
-- Run after schema.sql and policies.sql. Safe to re-run: every insert is an
-- upsert on the primary key.
--
-- Image URLs are null throughout. Upload photography to the product-images
-- and category-images buckets, then update the matching image_url column and
-- it renders immediately; until then the storefront draws its woven
-- placeholder in image_tone.
-- =============================================================================

begin;

-- Categories -----------------------------------------------------------------
insert into categories (id, name, slug, description, intro, image_url, image_alt, image_tone, display_order) values ('cat-kanchipuram', 'Kanchipuram Silk', 'kanchipuram-silk', 'Korvai borders, three-ply mulberry silk, woven in and around Kanchipuram.', 'The body and the border are woven separately and locked together by hand at the join. Hold a Kanchipuram up to the light and you can find that seam. It is the reason the border sits flat when the rest of the saree moves.', 'https://images.pexels.com/photos/1937336/pexels-photo-1937336.jpeg?auto=compress&cs=tinysrgb&w=1600', 'A folded Kanchipuram silk saree with a contrast korvai border', 'maroon', 1)
on conflict (id) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, intro = excluded.intro, image_alt = excluded.image_alt, image_tone = excluded.image_tone, display_order = excluded.display_order;
insert into categories (id, name, slug, description, intro, image_url, image_alt, image_tone, display_order) values ('cat-banarasi', 'Banarasi', 'banarasi', 'Brocade from the Varanasi looms, in katan silk and tissue.', 'Banaras weaves in metal. Kadhwa, cutwork, jangla, tissue: each is a different argument about how much gold a saree can carry before it stops being wearable. We buy the ones that stayed on the right side of that line.', 'https://images.pexels.com/photos/14380626/pexels-photo-14380626.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Gold brocade motifs across a Banarasi silk saree', 'ivory', 2)
on conflict (id) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, intro = excluded.intro, image_alt = excluded.image_alt, image_tone = excluded.image_tone, display_order = excluded.display_order;
insert into categories (id, name, slug, description, intro, image_url, image_alt, image_tone, display_order) values ('cat-organza', 'Organza', 'organza', 'Sheer, weightless, and sharper than it looks.', 'Organza holds its shape without any help. It photographs beautifully and it travels badly, so we ship it rolled.', 'https://images.pexels.com/photos/24781661/pexels-photo-24781661.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Sheer organza saree catching light against a wall', 'rose', 3)
on conflict (id) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, intro = excluded.intro, image_alt = excluded.image_alt, image_tone = excluded.image_tone, display_order = excluded.display_order;
insert into categories (id, name, slug, description, intro, image_url, image_alt, image_tone, display_order) values ('cat-linen', 'Linen', 'linen', 'Handwoven linen for the long working day.', 'Linen sarees crease within an hour of wearing them. We have stopped apologising for it. They also breathe through a Chennai May, which nothing else in this list can claim.', 'https://images.pexels.com/photos/10919577/pexels-photo-10919577.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Textured handwoven linen saree folded on a wooden surface', 'charcoal', 4)
on conflict (id) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, intro = excluded.intro, image_alt = excluded.image_alt, image_tone = excluded.image_tone, display_order = excluded.display_order;
insert into categories (id, name, slug, description, intro, image_url, image_alt, image_tone, display_order) values ('cat-cotton', 'Cotton', 'cotton', 'Everyday handloom cotton, mostly from Andhra and Bengal.', 'The kind of saree that gets worn twice a week and softens for years. Priced so that is possible.', 'https://images.pexels.com/photos/10992768/pexels-photo-10992768.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Striped handloom cotton saree stacked in a pile', 'indigo', 5)
on conflict (id) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, intro = excluded.intro, image_alt = excluded.image_alt, image_tone = excluded.image_tone, display_order = excluded.display_order;
insert into categories (id, name, slug, description, intro, image_url, image_alt, image_tone, display_order) values ('cat-chanderi', 'Chanderi', 'chanderi', 'Silk-cotton from Madhya Pradesh, with that particular glassy sheen.', 'Chanderi is not quite silk and not quite cotton, and it is the transparency that gives it away. Best in the small motifs, worst when someone tries to make it grand.', 'https://images.pexels.com/photos/14765912/pexels-photo-14765912.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Chanderi saree with fine gold butis held to the light', 'sand', 6)
on conflict (id) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, intro = excluded.intro, image_alt = excluded.image_alt, image_tone = excluded.image_tone, display_order = excluded.display_order;
insert into categories (id, name, slug, description, intro, image_url, image_alt, image_tone, display_order) values ('cat-printed', 'Printed', 'printed', 'Hand block and screen prints on soft grounds.', 'Block printing leaves a slightly uneven edge where the wooden block lifts. We look for that, not against it.', 'https://images.pexels.com/photos/37619027/pexels-photo-37619027.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Hand block printed saree with a repeating floral motif', 'terracotta', 7)
on conflict (id) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, intro = excluded.intro, image_alt = excluded.image_alt, image_tone = excluded.image_tone, display_order = excluded.display_order;
insert into categories (id, name, slug, description, intro, image_url, image_alt, image_tone, display_order) values ('cat-festive', 'Festive', 'festive', 'Pieces built for a room full of people and low light.', 'Festive sarees have to work under tube light, under a lamp and in a phone camera flash. These do.', 'https://images.pexels.com/photos/28943466/pexels-photo-28943466.jpeg?auto=compress&cs=tinysrgb&w=1600', 'A deep maroon festive saree with gold zari lit warmly', 'maroon', 8)
on conflict (id) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, intro = excluded.intro, image_alt = excluded.image_alt, image_tone = excluded.image_tone, display_order = excluded.display_order;
insert into categories (id, name, slug, description, intro, image_url, image_alt, image_tone, display_order) values ('cat-wedding', 'Wedding', 'wedding', 'The heavy pieces. Muhurtham silks and heirloom brocade.', 'A wedding saree is bought once and kept for forty years. We keep a small number and we tell you exactly what is in them.', 'https://images.pexels.com/photos/6045295/pexels-photo-6045295.jpeg?auto=compress&cs=tinysrgb&w=1600', 'A bridal silk saree with a wide gold border laid flat', 'saffron', 9)
on conflict (id) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, intro = excluded.intro, image_alt = excluded.image_alt, image_tone = excluded.image_tone, display_order = excluded.display_order;

-- Collections ----------------------------------------------------------------
insert into collections (id, name, slug, description, story, image_url, image_alt, image_tone, display_order) values ('col-new-season', 'The New Season', 'the-new-season', 'What came off the looms this quarter.', 'We went back to Kanchipuram in March with a narrower brief than usual: fewer colours, thinner borders, and nothing above nine hundred grams. What came back is quieter than last year and easier to wear twice in a week.', 'https://images.pexels.com/photos/10317106/pexels-photo-10317106.jpeg?auto=compress&cs=tinysrgb&w=1600', 'New season sarees folded and stacked in daylight', 'olive', 1)
on conflict (id) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, story = excluded.story, image_alt = excluded.image_alt, image_tone = excluded.image_tone, display_order = excluded.display_order;
insert into collections (id, name, slug, description, story, image_url, image_alt, image_tone, display_order) values ('col-silk-stories', 'Silk Stories', 'silk-stories', 'From the looms of Kanchipuram and Banaras to your wardrobe.', 'Six families weave for us. The oldest partnership is with Rathinam and his two sons on Salai Street, who have been putting korvai borders on our sarees since the first year. Everything here is three-ply mulberry silk with tested zari, and every piece carries the weaver''s name on its tag.', 'https://images.pexels.com/photos/33925037/pexels-photo-33925037.jpeg?auto=compress&cs=tinysrgb&w=1600', 'A weaver''s hands passing a shuttle across a silk warp', 'maroon', 2)
on conflict (id) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, story = excluded.story, image_alt = excluded.image_alt, image_tone = excluded.image_tone, display_order = excluded.display_order;
insert into collections (id, name, slug, description, story, image_url, image_alt, image_tone, display_order) values ('col-festive-edit', 'The Festive Edit', 'the-festive-edit', 'Deep grounds, restrained gold, built for lamplight.', 'Festive does not have to mean heavy. This edit keeps the colour deep and the zari sparing, so the saree reads rich from across a room without weighing on the shoulder by the end of the night.', 'https://images.pexels.com/photos/10211234/pexels-photo-10211234.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Festive sarees in maroon and saffron beside an oil lamp', 'saffron', 3)
on conflict (id) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, story = excluded.story, image_alt = excluded.image_alt, image_tone = excluded.image_tone, display_order = excluded.display_order;
insert into collections (id, name, slug, description, story, image_url, image_alt, image_tone, display_order) values ('col-everyday', 'Everyday Drape', 'everyday-drape', 'Cotton, linen and light chanderi for the working week.', 'The sarees we wear ourselves. Soft enough to sit in all day, cheap enough to not think about, and good enough that people ask where they are from.', 'https://images.pexels.com/photos/33433875/pexels-photo-33433875.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Cotton and linen sarees hanging on a rail', 'indigo', 4)
on conflict (id) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, story = excluded.story, image_alt = excluded.image_alt, image_tone = excluded.image_tone, display_order = excluded.display_order;
insert into collections (id, name, slug, description, story, image_url, image_alt, image_tone, display_order) values ('col-bridal', 'Bridal Heirloom', 'bridal-heirloom', 'A small, considered set of muhurtham silks.', 'We hold no more than eight bridal pieces at a time. Each one is documented: weaver, loom, zari assay, weight in grams. Come to Alwarpet and see them in daylight before you decide, or ask us to send the fabric card.', 'https://images.pexels.com/photos/39070874/pexels-photo-39070874.jpeg?auto=compress&cs=tinysrgb&w=1600', 'A bridal silk saree in arakku maroon with a wide gold border', 'saffron', 5)
on conflict (id) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, story = excluded.story, image_alt = excluded.image_alt, image_tone = excluded.image_tone, display_order = excluded.display_order;

-- Products -------------------------------------------------------------------
insert into products (id, name, slug, short_description, description, story, price, compare_at_price, fabric, color, tone, weave, craft_tags, occasions, length_metres, width_metres, blouse_piece, care, category_id, collection_id, stock_quantity, is_featured, is_new, is_active, created_at, updated_at) values ('prd-001', 'Anika Handwoven Silk Saree', 'anika-handwoven-silk-saree', 'A madder-red Kanchipuram with a mustard korvai border and a plain, unfussy pallu.', 'The body is a flat madder red with no motif at all, which is rarer than it sounds and much harder to weave well. The interest sits entirely in the border, where a mustard korvai is locked in by hand and edged with a single line of zari.

At around 620 grams it is a light Kanchipuram. It will hold a pleat through a long evening without asking anything of your shoulder.', 'Woven by Rathinam and his son Suresh on Salai Street, Kanchipuram, on a pit loom their family has used for three generations. The korvai join took eleven days.', 18500, null, 'Pure Kanchipuram Silk', 'Deep madder', 'maroon', 'Korvai, three-shuttle', '{"Handwoven","Korvai border","Tested zari"}', '{festive,ceremony}'::occasion[], 6.3, 1.15, '0.8m contrast blouse piece attached, in the border colour', '{"Dry clean only, and tell the cleaner it is pure zari.","Store folded in the cotton bag it arrived in. Refold along a new line every few months so the zari does not crease in one place.","Keep away from direct sunlight, damp and naphthalene."}', 'cat-kanchipuram', 'col-silk-stories', 4, true, false, true, '2025-07-29T00:00:00.000Z', '2025-07-31T00:00:00.000Z')
on conflict (id) do update set name = excluded.name, slug = excluded.slug, short_description = excluded.short_description, description = excluded.description, story = excluded.story, price = excluded.price, compare_at_price = excluded.compare_at_price, fabric = excluded.fabric, color = excluded.color, tone = excluded.tone, weave = excluded.weave, craft_tags = excluded.craft_tags, occasions = excluded.occasions, blouse_piece = excluded.blouse_piece, care = excluded.care, category_id = excluded.category_id, collection_id = excluded.collection_id, stock_quantity = excluded.stock_quantity, is_featured = excluded.is_featured, is_new = excluded.is_new, is_active = excluded.is_active;
insert into products (id, name, slug, short_description, description, story, price, compare_at_price, fabric, color, tone, weave, craft_tags, occasions, length_metres, width_metres, blouse_piece, care, category_id, collection_id, stock_quantity, is_featured, is_new, is_active, created_at, updated_at) values ('prd-002', 'Meera Peacock Silk Saree', 'meera-peacock-silk-saree', 'Peacock green with an ochre double-warp border and a pallu of small mango butis.', 'Peacock is the colour Kanchipuram does better than anywhere else, and this is a good one: green in daylight, closer to blue under a lamp. The rettai pettu border is woven with a doubled warp so it stands slightly proud of the body.

The pallu carries small mango butis rather than a full brocade panel. It keeps the weight down and stops the saree from tipping into bridal territory.', 'From the Vasanthi cooperative loom shed outside Kanchipuram, where eleven women weave under one roof. The zari is from Surat and assayed at 57 per cent silver.', 24800, null, 'Pure Kanchipuram Silk', 'Peacock green', 'teal', 'Korvai with rettai pettu border', '{"Handwoven","Double-warp border","Tested zari"}', '{festive,wedding}'::occasion[], 6.3, 1.15, '0.8m contrast blouse piece attached, in ochre', '{"Dry clean only, and tell the cleaner it is pure zari.","Store folded in the cotton bag it arrived in. Refold along a new line every few months so the zari does not crease in one place.","Keep away from direct sunlight, damp and naphthalene."}', 'cat-kanchipuram', 'col-new-season', 3, true, true, true, '2025-08-23T00:00:00.000Z', '2025-08-25T00:00:00.000Z')
on conflict (id) do update set name = excluded.name, slug = excluded.slug, short_description = excluded.short_description, description = excluded.description, story = excluded.story, price = excluded.price, compare_at_price = excluded.compare_at_price, fabric = excluded.fabric, color = excluded.color, tone = excluded.tone, weave = excluded.weave, craft_tags = excluded.craft_tags, occasions = excluded.occasions, blouse_piece = excluded.blouse_piece, care = excluded.care, category_id = excluded.category_id, collection_id = excluded.collection_id, stock_quantity = excluded.stock_quantity, is_featured = excluded.is_featured, is_new = excluded.is_new, is_active = excluded.is_active;
insert into products (id, name, slug, short_description, description, story, price, compare_at_price, fabric, color, tone, weave, craft_tags, occasions, length_metres, width_metres, blouse_piece, care, category_id, collection_id, stock_quantity, is_featured, is_new, is_active, created_at, updated_at) values ('prd-003', 'Ila Ivory Banarasi Saree', 'ila-ivory-banarasi-saree', 'Ivory katan silk with kadhwa jaal in antique gold, woven motif by motif.', 'Kadhwa means each motif is woven as its own small tapestry rather than carried across the back of the fabric. Turn the saree over: there are no floats, no cut threads, and the reverse is nearly as clean as the front.

The gold is antique-toned rather than bright, which is what keeps an ivory saree from looking like a costume.', 'Nine months on a jala loom in Lohta, on the edge of Varanasi. Irshad Ansari and his brother worked it between them, and the naqsha for the jaal is one his grandfather punched.', 32000, null, 'Katan Silk', 'Bone ivory', 'ivory', 'Kadhwa brocade', '{"Handwoven","Kadhwa","Real zari"}', '{wedding,ceremony}'::occasion[], 6.3, 1.15, '0.8m matching blouse piece, unstitched', '{"Dry clean only, and tell the cleaner it is pure zari.","Store folded in the cotton bag it arrived in. Refold along a new line every few months so the zari does not crease in one place.","Keep away from direct sunlight, damp and naphthalene."}', 'cat-banarasi', 'col-silk-stories', 2, true, false, true, '2025-07-02T00:00:00.000Z', '2025-07-04T00:00:00.000Z')
on conflict (id) do update set name = excluded.name, slug = excluded.slug, short_description = excluded.short_description, description = excluded.description, story = excluded.story, price = excluded.price, compare_at_price = excluded.compare_at_price, fabric = excluded.fabric, color = excluded.color, tone = excluded.tone, weave = excluded.weave, craft_tags = excluded.craft_tags, occasions = excluded.occasions, blouse_piece = excluded.blouse_piece, care = excluded.care, category_id = excluded.category_id, collection_id = excluded.collection_id, stock_quantity = excluded.stock_quantity, is_featured = excluded.is_featured, is_new = excluded.is_new, is_active = excluded.is_active;
insert into products (id, name, slug, short_description, description, story, price, compare_at_price, fabric, color, tone, weave, craft_tags, occasions, length_metres, width_metres, blouse_piece, care, category_id, collection_id, stock_quantity, is_featured, is_new, is_active, created_at, updated_at) values ('prd-004', 'Nithya Organza Saree', 'nithya-organza-saree', 'Sheer blush organza with a hand-embroidered scalloped edge in the same colour.', 'Tone-on-tone embroidery, so the border reads as texture rather than pattern. The scallop is cut and finished by hand, which is why no two edges are quite identical.

Organza needs a proper petticoat and a firm pin. Give it both and it holds a shape nothing else can.', 'Embroidered at a small unit in Chennai run by Fatima, who takes twenty pieces a month and no more.', 9800, null, 'Silk Organza', 'Blush', 'rose', 'Plain woven, hand-embroidered border', '{"Hand embroidery","Scalloped edge"}', '{ceremony,festive}'::occasion[], 6.3, 1.15, '0.8m raw silk blouse piece in the same blush', '{"Dry clean only.","Hang rather than fold, on a padded hanger, so the crispness holds.","Never wring. Never iron directly on the fabric, use a muslin cloth."}', 'cat-organza', 'col-new-season', 6, false, true, true, '2025-08-27T00:00:00.000Z', '2025-08-29T00:00:00.000Z')
on conflict (id) do update set name = excluded.name, slug = excluded.slug, short_description = excluded.short_description, description = excluded.description, story = excluded.story, price = excluded.price, compare_at_price = excluded.compare_at_price, fabric = excluded.fabric, color = excluded.color, tone = excluded.tone, weave = excluded.weave, craft_tags = excluded.craft_tags, occasions = excluded.occasions, blouse_piece = excluded.blouse_piece, care = excluded.care, category_id = excluded.category_id, collection_id = excluded.collection_id, stock_quantity = excluded.stock_quantity, is_featured = excluded.is_featured, is_new = excluded.is_new, is_active = excluded.is_active;
insert into products (id, name, slug, short_description, description, story, price, compare_at_price, fabric, color, tone, weave, craft_tags, occasions, length_metres, width_metres, blouse_piece, care, category_id, collection_id, stock_quantity, is_featured, is_new, is_active, created_at, updated_at) values ('prd-005', 'Vaidehi Indigo Banarasi Saree', 'vaidehi-indigo-banarasi-saree', 'Indigo katan with a creeping jangla vine in gold across the whole body.', 'Jangla covers the entire field with a single continuous vine, so there is no empty ground to break the pattern. On a dark indigo it reads almost like a night garden.

Heavier than our other Banarasis at 780 grams. Worth knowing before a long evening.', 'Woven in Ramnagar over seven months. The indigo is a chemical dye, not natural, and we would rather say so than let you assume otherwise.', 28400, null, 'Katan Silk', 'Deep indigo', 'indigo', 'Jangla brocade', '{"Handwoven","Jangla","Real zari"}', '{festive,wedding}'::occasion[], 6.3, 1.15, '0.8m matching blouse piece, unstitched', '{"Dry clean only, and tell the cleaner it is pure zari.","Store folded in the cotton bag it arrived in. Refold along a new line every few months so the zari does not crease in one place.","Keep away from direct sunlight, damp and naphthalene."}', 'cat-banarasi', 'col-new-season', 3, false, true, true, '2025-08-20T00:00:00.000Z', '2025-08-22T00:00:00.000Z')
on conflict (id) do update set name = excluded.name, slug = excluded.slug, short_description = excluded.short_description, description = excluded.description, story = excluded.story, price = excluded.price, compare_at_price = excluded.compare_at_price, fabric = excluded.fabric, color = excluded.color, tone = excluded.tone, weave = excluded.weave, craft_tags = excluded.craft_tags, occasions = excluded.occasions, blouse_piece = excluded.blouse_piece, care = excluded.care, category_id = excluded.category_id, collection_id = excluded.collection_id, stock_quantity = excluded.stock_quantity, is_featured = excluded.is_featured, is_new = excluded.is_new, is_active = excluded.is_active;
insert into products (id, name, slug, short_description, description, story, price, compare_at_price, fabric, color, tone, weave, craft_tags, occasions, length_metres, width_metres, blouse_piece, care, category_id, collection_id, stock_quantity, is_featured, is_new, is_active, created_at, updated_at) values ('prd-006', 'Suhasini Chanderi Saree', 'suhasini-chanderi-saree', 'Wheat chanderi scattered with small gold butis and a narrow zari edge.', 'The buti here is nakshi, woven with an extra weft rather than printed, so it has a slight raised feel under the thumb.

This is the saree we recommend to anyone buying their first handloom. It is forgiving to drape, light enough for an office day, and smart enough for a lunch afterwards.', 'From Chanderi town, Madhya Pradesh, through a cooperative we have bought from since 2018.', 7200, null, 'Chanderi Silk-Cotton', 'Wheat', 'sand', 'Plain with gold butis', '{"Handwoven","Nakshi buti"}', '{work,everyday,ceremony}'::occasion[], 6.3, 1.15, '0.8m matching blouse piece, unstitched', '{"Dry clean recommended for the first year.","Store rolled rather than sharply folded, the silk-cotton mix marks easily.","Steam iron on low, always on the reverse."}', 'cat-chanderi', 'col-everyday', 8, false, false, true, '2025-06-15T00:00:00.000Z', '2025-06-17T00:00:00.000Z')
on conflict (id) do update set name = excluded.name, slug = excluded.slug, short_description = excluded.short_description, description = excluded.description, story = excluded.story, price = excluded.price, compare_at_price = excluded.compare_at_price, fabric = excluded.fabric, color = excluded.color, tone = excluded.tone, weave = excluded.weave, craft_tags = excluded.craft_tags, occasions = excluded.occasions, blouse_piece = excluded.blouse_piece, care = excluded.care, category_id = excluded.category_id, collection_id = excluded.collection_id, stock_quantity = excluded.stock_quantity, is_featured = excluded.is_featured, is_new = excluded.is_new, is_active = excluded.is_active;
