insert into products (id, name, slug, short_description, description, story, price, compare_at_price, fabric, color, tone, weave, craft_tags, occasions, length_metres, width_metres, blouse_piece, care, category_id, collection_id, stock_quantity, is_featured, is_new, is_active, created_at, updated_at) values ('prd-020', 'Shakuntala Tissue Banarasi Saree', 'shakuntala-tissue-banarasi-saree', 'Champagne tissue shot through with gold, with widely spaced kadhwa butis.', 'Tissue is silk woven with a zari weft, so the whole cloth carries a metallic ground rather than a metallic pattern. It changes colour completely depending on where you stand.

We have spaced the butis wide on purpose. On tissue, more would be too much.', 'Lohta, Varanasi. Irshad''s loom, seven months.', 44000, null, 'Silk Tissue', 'Champagne', 'ivory', 'Tissue with kadhwa buti', '{"Handwoven","Tissue","Kadhwa","Real zari"}', '{wedding,ceremony}'::occasion[], 6.3, 1.15, '0.8m matching tissue blouse piece', '{"Dry clean only, and tell the cleaner it is pure zari.","Store folded in the cotton bag it arrived in. Refold along a new line every few months so the zari does not crease in one place.","Keep away from direct sunlight, damp and naphthalene."}', 'cat-banarasi', 'col-bridal', 2, false, false, true, '2025-08-06T00:00:00.000Z', '2025-08-08T00:00:00.000Z')
