insert into products (id, name, slug, short_description, description, story, price, compare_at_price, fabric, color, tone, weave, craft_tags, occasions, length_metres, width_metres, blouse_piece, care, category_id, collection_id, stock_quantity, is_featured, is_new, is_active, created_at, updated_at) values ('prd-021', 'Devika Everyday Cotton Saree', 'devika-everyday-cotton-saree', 'Sage cotton with a rust border, which is the most useful colour pair we know.', 'Sage and rust is a combination that goes with almost every blouse already in a wardrobe, which is the whole argument for this saree.

Soft from the first wear rather than the tenth, because the yarn is loosely spun.', 'Srikalahasti, Andhra Pradesh.', 3500, null, 'Handloom Cotton', 'Sage', 'olive', 'Plain weave with contrast border', '{"Handwoven"}', '{everyday,work}'::occasion[], 6.3, 1.15, '0.8m contrast cotton blouse piece in rust', '{"First wash separately in cold water. The colour will settle after two or three washes.","Gentle hand wash with a mild detergent. No bleach, no brush.","Dry in shade and steam iron while very slightly damp."}', 'cat-cotton', 'col-everyday', 14, false, true, true, '2025-08-28T00:00:00.000Z', '2025-08-30T00:00:00.000Z')
on conflict (id) do update set name = excluded.name, slug = excluded.slug, short_description = excluded.short_description, description = excluded.description, story = excluded.story, price = excluded.price, compare_at_price = excluded.compare_at_price, fabric = excluded.fabric, color = excluded.color, tone = excluded.tone, weave = excluded.weave, craft_tags = excluded.craft_tags, occasions = excluded.occasions, blouse_piece = excluded.blouse_piece, care = excluded.care, category_id = excluded.category_id, collection_id = excluded.collection_id, stock_quantity = excluded.stock_quantity, is_featured = excluded.is_featured, is_new = excluded.is_new, is_active = excluded.is_active;
insert into products (id, name, slug, short_description, description, story, price, compare_at_price, fabric, color, tone, weave, craft_tags, occasions, length_metres, width_metres, blouse_piece, care, category_id, collection_id, stock_quantity, is_featured, is_new, is_active, created_at, updated_at) values ('prd-022', 'Sharada Chanderi Saree', 'sharada-chanderi-saree', 'Charcoal chanderi with silver rather than gold butis and a plain silver edge.', 'Silver zari on charcoal is a cooler register than chanderi usually works in, and it takes the saree out of the daytime and into an evening.

The transparency is still there. Chanderi at this count always needs a well-fitted petticoat.', 'Chanderi town, Madhya Pradesh.', 9400, null, 'Chanderi Silk-Cotton', 'Charcoal', 'charcoal', 'Plain with silver butis', '{"Handwoven","Silver zari"}', '{work,ceremony,festive}'::occasion[], 6.3, 1.15, '0.8m matching blouse piece, unstitched', '{"Dry clean recommended for the first year.","Store rolled rather than sharply folded, the silk-cotton mix marks easily.","Steam iron on low, always on the reverse."}', 'cat-chanderi', 'col-new-season', 6, false, true, true, '2025-08-24T00:00:00.000Z', '2025-08-26T00:00:00.000Z')
on conflict (id) do update set name = excluded.name, slug = excluded.slug, short_description = excluded.short_description, description = excluded.description, story = excluded.story, price = excluded.price, compare_at_price = excluded.compare_at_price, fabric = excluded.fabric, color = excluded.color, tone = excluded.tone, weave = excluded.weave, craft_tags = excluded.craft_tags, occasions = excluded.occasions, blouse_piece = excluded.blouse_piece, care = excluded.care, category_id = excluded.category_id, collection_id = excluded.collection_id, stock_quantity = excluded.stock_quantity, is_featured = excluded.is_featured, is_new = excluded.is_new, is_active = excluded.is_active;
insert into products (id, name, slug, short_description, description, story, price, compare_at_price, fabric, color, tone, weave, craft_tags, occasions, length_metres, width_metres, blouse_piece, care, category_id, collection_id, stock_quantity, is_featured, is_new, is_active, created_at, updated_at) values ('prd-023', 'Yashodha Mustard Silk Saree', 'yashodha-mustard-silk-saree', 'Mustard silk with a bottle green thread border and no zari at all.', 'A thread border instead of a zari one, which halves the weight and changes the whole character of the saree. It reads as a daytime Kanchipuram, if such a thing exists.

540 grams, the lightest silk we stock.', 'Part of the narrower brief we took to Kanchipuram in March: fewer colours, thinner borders, nothing above nine hundred grams.', 26700, null, 'Pure Kanchipuram Silk', 'Mustard', 'saffron', 'Korvai with thread border', '{"Handwoven","Korvai border","Thread border"}', '{festive,ceremony}'::occasion[], 6.3, 1.15, '0.8m contrast blouse piece in bottle green', '{"Dry clean only, and tell the cleaner it is pure zari.","Store folded in the cotton bag it arrived in. Refold along a new line every few months so the zari does not crease in one place.","Keep away from direct sunlight, damp and naphthalene."}', 'cat-kanchipuram', 'col-new-season', 4, false, true, true, '2025-08-22T00:00:00.000Z', '2025-08-24T00:00:00.000Z')
on conflict (id) do update set name = excluded.name, slug = excluded.slug, short_description = excluded.short_description, description = excluded.description, story = excluded.story, price = excluded.price, compare_at_price = excluded.compare_at_price, fabric = excluded.fabric, color = excluded.color, tone = excluded.tone, weave = excluded.weave, craft_tags = excluded.craft_tags, occasions = excluded.occasions, blouse_piece = excluded.blouse_piece, care = excluded.care, category_id = excluded.category_id, collection_id = excluded.collection_id, stock_quantity = excluded.stock_quantity, is_featured = excluded.is_featured, is_new = excluded.is_new, is_active = excluded.is_active;
insert into products (id, name, slug, short_description, description, story, price, compare_at_price, fabric, color, tone, weave, craft_tags, occasions, length_metres, width_metres, blouse_piece, care, category_id, collection_id, stock_quantity, is_featured, is_new, is_active, created_at, updated_at) values ('prd-024', 'Uma Linen Saree', 'uma-linen-saree', 'Brick red linen in a fine 120 count, with a self-coloured border.', '120 count is as fine as handwoven linen gets before it stops behaving like linen. It drapes almost like a soft silk and still breathes.

The border is the same colour as the body, marked only by a change in the weave.', 'Bhoodan Pochampally, Telangana.', 5800, null, 'Handwoven Linen', 'Brick', 'terracotta', 'Plain weave, 120 count', '{"Handwoven","120 count linen"}', '{work,everyday}'::occasion[], 6.3, 1.15, '0.8m matching linen blouse piece', '{"Gentle hand wash in cold water, or dry clean if you prefer the crisp finish.","Dry flat in shade. Linen creases, that is the point of it.","Iron on a medium setting while damp."}', 'cat-linen', 'col-everyday', 8, false, false, true, '2025-07-19T00:00:00.000Z', '2025-07-21T00:00:00.000Z')
on conflict (id) do update set name = excluded.name, slug = excluded.slug, short_description = excluded.short_description, description = excluded.description, story = excluded.story, price = excluded.price, compare_at_price = excluded.compare_at_price, fabric = excluded.fabric, color = excluded.color, tone = excluded.tone, weave = excluded.weave, craft_tags = excluded.craft_tags, occasions = excluded.occasions, blouse_piece = excluded.blouse_piece, care = excluded.care, category_id = excluded.category_id, collection_id = excluded.collection_id, stock_quantity = excluded.stock_quantity, is_featured = excluded.is_featured, is_new = excluded.is_new, is_active = excluded.is_active;
insert into products (id, name, slug, short_description, description, story, price, compare_at_price, fabric, color, tone, weave, craft_tags, occasions, length_metres, width_metres, blouse_piece, care, category_id, collection_id, stock_quantity, is_featured, is_new, is_active, created_at, updated_at) values ('prd-025', 'Bhavani Festive Silk Saree', 'bhavani-festive-silk-saree', 'Plum semi-silk with a gold jacquard border, made to be worn often.', 'Semi-silk gets a bad name and it should not. It is a silk warp with a cotton weft, which gives you the sheen and the drape at a third of the weight and a fraction of the price.

This is the saree for the third day of a wedding, when the good silk has already had its outing.', 'Powerloom-woven in Salem, and we will not pretend otherwise. Good value, honestly made.', 13900, 15500, 'Semi-Silk', 'Deep plum', 'maroon', 'Jacquard with zari border', '{"Zari border","Jacquard"}', '{festive}'::occasion[], 6.3, 1.15, '0.8m matching blouse piece, unstitched', '{"Dry clean only, and tell the cleaner it is pure zari.","Store folded in the cotton bag it arrived in. Refold along a new line every few months so the zari does not crease in one place.","Keep away from direct sunlight, damp and naphthalene."}', 'cat-festive', 'col-festive-edit', 7, true, false, true, '2025-08-13T00:00:00.000Z', '2025-08-15T00:00:00.000Z')
on conflict (id) do update set name = excluded.name, slug = excluded.slug, short_description = excluded.short_description, description = excluded.description, story = excluded.story, price = excluded.price, compare_at_price = excluded.compare_at_price, fabric = excluded.fabric, color = excluded.color, tone = excluded.tone, weave = excluded.weave, craft_tags = excluded.craft_tags, occasions = excluded.occasions, blouse_piece = excluded.blouse_piece, care = excluded.care, category_id = excluded.category_id, collection_id = excluded.collection_id, stock_quantity = excluded.stock_quantity, is_featured = excluded.is_featured, is_new = excluded.is_new, is_active = excluded.is_active;
insert into products (id, name, slug, short_description, description, story, price, compare_at_price, fabric, color, tone, weave, craft_tags, occasions, length_metres, width_metres, blouse_piece, care, category_id, collection_id, stock_quantity, is_featured, is_new, is_active, created_at, updated_at) values ('prd-026', 'Malini Festive Saree', 'malini-festive-saree', 'Bottle green semi-silk with a gold brocade pallu and a narrow matching border.', 'The pallu does all the work here. Two feet of gold brocade against a plain green body, so the saree is quiet from the front and considerable from behind.

Holds a pleat well and packs small, which makes it the one we suggest for travel.', 'Salem, Tamil Nadu.', 15600, null, 'Semi-Silk', 'Bottle green', 'olive', 'Jacquard with brocade pallu', '{"Zari border","Brocade pallu"}', '{festive,ceremony}'::occasion[], 6.3, 1.15, '0.8m contrast blouse piece in gold', '{"Dry clean only, and tell the cleaner it is pure zari.","Store folded in the cotton bag it arrived in. Refold along a new line every few months so the zari does not crease in one place.","Keep away from direct sunlight, damp and naphthalene."}', 'cat-festive', 'col-festive-edit', 5, false, false, true, '2025-08-03T00:00:00.000Z', '2025-08-05T00:00:00.000Z')
on conflict (id) do update set name = excluded.name, slug = excluded.slug, short_description = excluded.short_description, description = excluded.description, story = excluded.story, price = excluded.price, compare_at_price = excluded.compare_at_price, fabric = excluded.fabric, color = excluded.color, tone = excluded.tone, weave = excluded.weave, craft_tags = excluded.craft_tags, occasions = excluded.occasions, blouse_piece = excluded.blouse_piece, care = excluded.care, category_id = excluded.category_id, collection_id = excluded.collection_id, stock_quantity = excluded.stock_quantity, is_featured = excluded.is_featured, is_new = excluded.is_new, is_active = excluded.is_active;
insert into products (id, name, slug, short_description, description, story, price, compare_at_price, fabric, color, tone, weave, craft_tags, occasions, length_metres, width_metres, blouse_piece, care, category_id, collection_id, stock_quantity, is_featured, is_new, is_active, created_at, updated_at) values ('prd-027', 'Gauri Muhurtham Saree', 'gauri-muhurtham-saree', 'Kumkum red with a green korvai border and a full annapakshi brocade pallu.', 'Red and green is the oldest muhurtham pairing there is, and the annapakshi pallu is the oldest motif. There is nothing modern about this saree and there is not meant to be.

1,280 grams. Woven to be worn once and then kept.', 'Five months on Rathinam''s own loom, the last full brocade pallu he plans to weave himself. Zari assayed at 63 per cent silver, certificate included.', 68000, null, 'Pure Kanchipuram Silk', 'Kumkum red', 'maroon', 'Korvai with full brocade pallu', '{"Handwoven","Korvai border","Tested zari","Brocade pallu","Heirloom weight"}', '{wedding}'::occasion[], 6.3, 1.15, '0.9m contrast blouse piece in green, with woven border', '{"Dry clean only, and tell the cleaner it is pure zari.","Store folded in the cotton bag it arrived in. Refold along a new line every few months so the zari does not crease in one place.","Keep away from direct sunlight, damp and naphthalene."}', 'cat-wedding', 'col-bridal', 1, true, false, true, '2025-08-17T00:00:00.000Z', '2025-08-19T00:00:00.000Z')
